#!/bin/bash
# F3: all screen runs, one after another (no parallel browsers -> no shared-location swap). Outputs /tmp/cln/f3/*.out
cd "$(dirname "$0")"
TZ=Asia/Karachi timeout 900 node screen_tax.mjs hd RECHECK-b8ad4001/SV-11949 CM2-4520 '[{"name":"i-custom-oct20","range":["custom","10/20/2026","10/20/2026"],"rates":1},{"name":"ii-default-this-month","rates":1,"shotRates":1},{"name":"iii-this-year","range":["this_year"],"rates":1},{"name":"iii-this-year-paid","range":["this_year"],"status":"Paid"},{"name":"iii-this-year-partially","range":["this_year"],"status":"Partially Paid"}]' > /tmp/cln/f3/tax_hd.b8ad4001.out 2>&1
TZ=America/Toronto timeout 1200 node screen_tax.mjs dvi RECHECK-b8ad4001/SV-11950_51 S1-38218,S1-38221 '[{"name":"i-custom-oct28-as-ticket-today","range":["custom","10/28/2026","10/28/2026"]},{"name":"i-custom-oct28-partially","range":["custom","10/28/2026","10/28/2026"],"status":"Partially Paid"},{"name":"i-today-now","range":["today"]},{"name":"ii-default-this-month","shot":1},{"name":"ii-default-partially","status":"Partially Paid","shot":1},{"name":"iii-this-year","range":["this_year"]},{"name":"iii-this-year-partially","range":["this_year"],"status":"Partially Paid"}]' > /tmp/cln/f3/tax_dvi.b8ad4001.out 2>&1
TICKET_DIR=RECHECK-b8ad4001/SV-11952 TZ=America/Toronto timeout 900 node screen_sbr.mjs '[{"name":"i-ticket-thismonth-unassigned","unassigned":1,"expand":"unassigned"},{"name":"ii-default-expand-all","expand":"all","shot":1,"shotDay":"Oct 28 2026"},{"name":"iii-thisyear-unassigned-expand-all","preset":"This year","unassigned":1,"expand":"all"}]' > /tmp/cln/f3/sbr.b8ad4001.out 2>&1
TZ=America/Edmonton timeout 900 node screen_ap.mjs leth RECHECK-b8ad4001/SV-11922 '[{"name":"i-detail-oct28-ticket","path":"/reports/ap-aging-detail","day":28,"open":"Current","rows":["SV10190-ST1","976974"]},{"name":"ii-detail-default-today","path":"/reports/ap-aging-detail","open":"Current","rows":["SV10190-ST1","976974"],"shot":1},{"name":"ii-unpaid-default-no-vendor","path":"/reports/ap-unpaid-invoices","expandVendors":1,"rows":["SV10190-ST1","976974","5363"]},{"name":"i-unpaid-picture2-vendor-oct20","path":"/reports/ap-unpaid-invoices","query":"?asOfDate=2026-10-20&vendorId=68c72fe7-8fbe-4795-85aa-7e91fbb54c7e","expandVendors":1,"rows":["SV10190-ST1","5363"]},{"name":"iii-unpaid-oct20-no-vendor","path":"/reports/ap-unpaid-invoices","day":20,"expandVendors":1,"rows":["SV10190-ST1","5363"]}]' > /tmp/cln/f3/ap.b8ad4001.out 2>&1
TZ=Asia/Karachi timeout 900 node screen_ap.mjs hd RECHECK-b8ad4001/SV-11935 '[{"name":"ii-ar-detail-default-today","path":"/reports/ar-aging-detail","open":"Current","rows":["P2-2352","P2-2439"],"shot":1},{"name":"iii-ar-detail-oct31","path":"/reports/ar-aging-detail","open":"Current","day":31,"rows":["P2-2352","P2-2439"]}]' > /tmp/cln/f3/ar_hd.b8ad4001.out 2>&1
TZ=America/Toronto timeout 900 node screen_ap.mjs dvi RECHECK-b8ad4001/SV-11935 '[{"name":"iii-ar-detail-from-dvi","path":"/reports/ar-aging-detail","open":"Current","rows":["P2-2352","P2-2439"]}]' > /tmp/cln/f3/ar_dvi.b8ad4001.out 2>&1
SBR_TAG=alllocs TICKET_DIR=RECHECK-b8ad4001/SV-11952 TZ=America/Toronto timeout 900 node screen_sbr.mjs '[{"name":"ii-all-locations-viktoria-oct07","clearLoc":1,"expand":"rep:04fc7976-76b8-4b3e-97a5-6cfdb2f96f3c","shot":1,"shotDay":"Oct 07 2026"},{"name":"iii-all-locations-thisyear-unassigned","clearLoc":1,"preset":"This year","unassigned":1,"expand":"unassigned"}]' > /tmp/cln/f3/sbr_all.b8ad4001.out 2>&1
TICKET_DIR=RECHECK-b8ad4001/SIDE1 TZ=America/Toronto timeout 500 node side1_screen.mjs > /tmp/cln/f3/side1.b8ad4001.out 2>&1
echo ALLDONE > /tmp/cln/f3/screens2.done
